import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const modules = [
  "utils/id",
  "utils/html",
  "utils/scrollPosition",
  "data/seed",
  "domain/workflowModel",
  "domain/workflowEngine",
  "infrastructure/apiRepository",
  "services/workflowTransfer",
  "components/workflowMap",
  "components/layout",
  "components/dashboard",
  "components/workflowEditor",
  "components/runView",
  "app",
];

function resolveImport(moduleName, specifier) {
  const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(moduleName), specifier));
  return resolved.replace(/\.js$/, "");
}

function compileModule(moduleName) {
  const filename = path.join(projectRoot, "src", `${moduleName}.js`);
  let source = fs.readFileSync(filename, "utf8");
  const exports = [];

  source = source.replace(
    /import\s*\{([^}]*)\}\s*from\s*["']([^"']+)["'];?/g,
    (_, names, specifier) => {
      const dependency = resolveImport(moduleName, specifier);
      if (!modules.includes(dependency) || modules.indexOf(dependency) >= modules.indexOf(moduleName)) {
        throw new Error(`${moduleName}: dependency ${dependency} is missing or must be bundled earlier`);
      }
      return `const { ${names.trim()} } = __flowlineModules["${dependency}"];`;
    },
  );
  source = source.replace(/export\s+(const|function|class)\s+([A-Za-z_$][\w$]*)/g, (_, kind, name) => {
    exports.push(name);
    return `${kind} ${name}`;
  });

  const assignment = moduleName === "app"
    ? ""
    : `\n__flowlineModules["${moduleName}"] = { ${exports.join(", ")} };`;
  return `// ${moduleName}.js\n(function () {\n${source}${assignment}\n})();`;
}

const banner = `/* Generated by scripts/build-classic-bundle.mjs. Do not edit directly. */\n(function () {\n"use strict";\nconst __flowlineModules = Object.create(null);`;
const output = `${banner}\n${modules.map(compileModule).join("\n\n")}\n})();\n`;
fs.writeFileSync(path.join(projectRoot, "src", "app.bundle.js"), output, "utf8");
console.log(`Built src/app.bundle.js (${Buffer.byteLength(output)} bytes)`);
